<?php
namespace App\Http\Controllers\Platform;
use App\Http\Controllers\Shared\BaseApiController;use App\Models\PlatformPermission;use App\Services\Rbac\RbacAuditLogger;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PlatformPermissionController extends BaseApiController{public function __construct(private readonly RbacAuditLogger $audit){}public function index(Request $r){$q=PlatformPermission::query()->withCount('roles');if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('display_name','like','%'.$r->search.'%'));foreach(['module','guard_name','status']as$f)if($r->filled('filter.'.$f))$q->where($f,$r->input('filter.'.$f));$p=$q->orderBy('module')->orderBy('name')->paginate((int)$r->integer('per_page',50));return $this->list($p->items(),$p);}public function grouped(){return $this->success(['permissions'=>$this->group(PlatformPermission::query()->where('status','active')->orderBy('module')->orderBy('name')->get())]);}public function store(Request $r){$p=PlatformPermission::query()->create($this->data($r));$this->audit->log($r,'platform_permission_created',$p,null,$p->toArray());return $this->success(['permission'=>$p],'Permission created.',201);}public function show($id){return $this->success(['permission'=>PlatformPermission::query()->where('uuid',$id)->withCount('roles')->firstOrFail()]);}public function update(Request $r,$id){$p=PlatformPermission::query()->where('uuid',$id)->firstOrFail();if($p->is_system&&$r->filled('name')&&$r->input('name')!==$p->name)return $this->businessError('System permissions cannot be renamed.','SYSTEM_PERMISSION_RENAME_FORBIDDEN',403);$old=$p->toArray();$p->fill($this->data($r,$p))->save();$this->audit->log($r,'platform_permission_updated',$p,$old,$p->fresh()->toArray());return $this->success(['permission'=>$p->fresh()],'Permission updated.');}public function destroy(Request $r,$id){$p=PlatformPermission::query()->where('uuid',$id)->firstOrFail();if($p->is_system)return $this->businessError('System permissions cannot be deleted.','SYSTEM_PERMISSION_DELETE_FORBIDDEN',403);if($p->roles()->exists())return $this->businessError('Assigned permissions cannot be deleted.','PERMISSION_IN_USE',409);$old=$p->toArray();$p->delete();$this->audit->log($r,'platform_permission_deleted',$p,$old,null);return $this->success(null,'Permission deleted.');}private function data(Request $r,?PlatformPermission $p=null){$guard=(string)$r->input('guard_name',$p?->guard_name??'platform');return $r->validate(['module'=>[$p?'sometimes':'required','string','max:100'],'name'=>[$p?'sometimes':'required','string','max:150',Rule::unique('platform_permissions')->where('guard_name',$guard)->ignore($p?->id)],'display_name'=>['nullable','string','max:150'],'guard_name'=>['sometimes','string','max:50'],'description'=>['nullable','string','max:255'],'is_system'=>['sometimes','boolean'],'status'=>['sometimes',Rule::in(['active','inactive'])]]);}private function group($permissions){return $permissions->groupBy('module')->map(fn($items)=>$items->values()->all())->all();}}
